CREATE TABLE IF NOT EXISTS "BIT240038_DishCategories" (
    "BIT240038_Id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BIT240038_Name" VARCHAR(100) NOT NULL,
    "BIT240038_Description" VARCHAR(2000)
);
CREATE TABLE IF NOT EXISTS "BIT240038_Dishes" (
    "BIT240038_Id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BIT240038_Name" VARCHAR(120) NOT NULL,
    "BIT240038_Price" NUMERIC(12,2) NOT NULL CHECK ("BIT240038_Price" > 0),
    "BIT240038_PreparationTime" INTEGER NOT NULL CHECK ("BIT240038_PreparationTime" > 0),
    "BIT240038_IsAvailable" BOOLEAN NOT NULL,
    "BIT240038_Description" VARCHAR(2000),
    "BIT240038_DishCategoryId" BIGINT NOT NULL,
    CONSTRAINT "BIT240038_FK_DishCategory" FOREIGN KEY ("BIT240038_DishCategoryId")
        REFERENCES "BIT240038_DishCategories" ("BIT240038_Id")
);
CREATE TABLE IF NOT EXISTS "BIT240038_DishImages" (
    "BIT240038_Id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BIT240038_ImageUrl" VARCHAR(2048) NOT NULL,
    "BIT240038_IsThumbnail" BOOLEAN NOT NULL,
    "BIT240038_DishId" BIGINT NOT NULL,
    CONSTRAINT "BIT240038_FK_DishImage" FOREIGN KEY ("BIT240038_DishId")
        REFERENCES "BIT240038_Dishes" ("BIT240038_Id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "BIT240038_UQ_CategoryName"
    ON "BIT240038_DishCategories" (LOWER(TRIM("BIT240038_Name")));
CREATE UNIQUE INDEX IF NOT EXISTS "BIT240038_UQ_DishCategoryName"
    ON "BIT240038_Dishes" ("BIT240038_DishCategoryId", LOWER(TRIM("BIT240038_Name")));
CREATE UNIQUE INDEX IF NOT EXISTS "BIT240038_UQ_Thumbnail"
    ON "BIT240038_DishImages" ("BIT240038_DishId") WHERE "BIT240038_IsThumbnail" = TRUE;
CREATE INDEX IF NOT EXISTS "BIT240038_IX_ImageDish"
    ON "BIT240038_DishImages" ("BIT240038_DishId");
